{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([session("a", 1, True), session("b", 1, None)]) == 0.5
    assert conversion_rate([]) == 0.0
    assert conversion_rate([session("a", 1, None), session("b", 1, False)]) == 0.0


def test_pooled_rate_weights_sessions_and_handles_empty_groups():
    groups = {"small": [session("a", 1, True)],
              "large": [session(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({}) == 0.0
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_session_log_flags_whitespace_and_skipped_lines():
    lines = ["\n", "  # comment,anything\n", "  a  ,  2 , 1 ",
             "b, 3, 0", " c,4,  "]
    assert parse_session_log(lines) == [session("a", 2, True),
                                        session("b", 3, False),
                                        session("c", 4, None)]


@pytest.mark.parametrize("bad_line", ["id,1", "id,1,1,extra", "id,nope,1", "id,1,yes"])
def test_parse_session_log_errors_report_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log([" ", " # skipped", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts_by_day_then_id():
    old = session("a", 10, True)
    last = session("a", 2, False)
    b = session("b", 2, True)
    c = session("c", 1, None)
    assert dedupe_sessions([old, b, c, last]) == [c, last, b]


def test_daily_conversion_counts_range_and_gaps():
    events = [session("a", 0, True), session("b", 1, True),
              session("c", 1, True), session("d", 2, None),
              session("e", 3, False), session("f", 4, True)]
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 0]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 4, False), session("c", 4, True)], "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "a": [session("a", 1, True)], "b": [session("b", 1, False)]}
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_includes_empty_and_sorts_keys():
    groups = {"z": [], "b": [session("b", 1, None)], "a": [session("a", 1, True)]}
    result = conversion_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_conversion_streak_resets_and_only_counts_positive():
    assert longest_conversion_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_conversion_streak([0, -1, 0]) == 0
    assert longest_conversion_streak([]) == 0
